CREATE TABLE IF NOT EXISTS __SCHEMA__.accounts(id TEXT PRIMARY KEY,username TEXT UNIQUE,name TEXT,password TEXT,salt TEXT,person_id TEXT,created BIGINT);
CREATE TABLE IF NOT EXISTS __SCHEMA__.sessions(hash TEXT PRIMARY KEY,account_id TEXT REFERENCES __SCHEMA__.accounts(id),expires BIGINT);
CREATE INDEX IF NOT EXISTS session_account ON __SCHEMA__.sessions(account_id);
CREATE TABLE IF NOT EXISTS __SCHEMA__.people(id TEXT PRIMARY KEY,name TEXT,creator TEXT,claimed_by TEXT,canonical TEXT,color TEXT,face INTEGER,sample INTEGER DEFAULT 0,created BIGINT);
CREATE INDEX IF NOT EXISTS people_canonical ON __SCHEMA__.people(canonical);
CREATE TABLE IF NOT EXISTS __SCHEMA__.relationships(author TEXT,person TEXT,created BIGINT,PRIMARY KEY(author,person));
CREATE TABLE IF NOT EXISTS __SCHEMA__.traits(id TEXT PRIMARY KEY,author TEXT,person TEXT,type TEXT,created BIGINT,UNIQUE(author,person,type));
CREATE TABLE IF NOT EXISTS __SCHEMA__.revisions(id TEXT PRIMARY KEY,trait_id TEXT,name TEXT,description TEXT,ability JSONB,status TEXT,created BIGINT,reviewed BIGINT);
CREATE INDEX IF NOT EXISTS rev_trait ON __SCHEMA__.revisions(trait_id,created DESC);
CREATE INDEX IF NOT EXISTS trait_person ON __SCHEMA__.traits(person,author);
CREATE TABLE IF NOT EXISTS __SCHEMA__.invites(hash TEXT PRIMARY KEY,person TEXT,creator TEXT,expires BIGINT,used INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS __SCHEMA__.decks(id TEXT PRIMARY KEY,owner TEXT,name TEXT,cards JSONB,reserve TEXT,updated BIGINT);
CREATE INDEX IF NOT EXISTS deck_owner ON __SCHEMA__.decks(owner);
CREATE TABLE IF NOT EXISTS __SCHEMA__.card_versions(id TEXT PRIMARY KEY,owner TEXT,person TEXT,definition JSONB,created BIGINT);
CREATE TABLE IF NOT EXISTS __SCHEMA__.matches(id TEXT,owner TEXT,result TEXT,opponent TEXT,details JSONB,created BIGINT,PRIMARY KEY(id,owner));
CREATE INDEX IF NOT EXISTS match_owner ON __SCHEMA__.matches(owner,created DESC);
CREATE TABLE IF NOT EXISTS __SCHEMA__.rooms(code TEXT PRIMARY KEY,state JSONB NOT NULL,version BIGINT NOT NULL,next_tick BIGINT NOT NULL,expires BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS room_due ON __SCHEMA__.rooms(next_tick);
CREATE TABLE IF NOT EXISTS __SCHEMA__.memberships(user_id TEXT PRIMARY KEY REFERENCES __SCHEMA__.accounts(id),code TEXT REFERENCES __SCHEMA__.rooms(code) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS membership_room ON __SCHEMA__.memberships(code);
CREATE TABLE IF NOT EXISTS __SCHEMA__.connections(user_id TEXT PRIMARY KEY REFERENCES __SCHEMA__.accounts(id),connection_id TEXT,last_seen BIGINT,expires BIGINT);
CREATE TABLE IF NOT EXISTS __SCHEMA__.rate_limits(key TEXT PRIMARY KEY,until_ms BIGINT,count INTEGER);
CREATE TABLE IF NOT EXISTS __SCHEMA__.social_refresh(user_id TEXT PRIMARY KEY,version BIGINT NOT NULL DEFAULT 1);
